func satSubUint32AVX512Guarded(dst []uint32, a []uint32, b []uint32) {
	n := min(len(dst), len(a), len(b))
	if n < 16 {
		ref.SatSub(dst, a, b)
		return
	}
	satSubUint32AVX512(dst[:n:n], a, b)
}

